SELECT EXISTS(
  SELECT 1 FROM new_contract.insurance_product_payment_mode
   WHERE product_code=#{productCode} AND product_version=#{productVersion}
     AND payment_mode_code=#{paymentModeCode}
)

SELECT EXISTS(
  SELECT 1 FROM new_contract.insurance_product_rider_rule
   WHERE base_product_code=#{baseProductCode} AND base_product_version=#{baseProductVersion}
     AND rider_product_code=#{riderProductCode} AND rider_product_version=#{riderProductVersion}
)
